const fs = require('fs');
const path = require('path');
const ts = require('/opt/typescript/lib/typescript.js');
const ctx = JSON.parse(fs.readFileSync('/work/context.json', 'utf8'));
const configPath = path.join(ctx.workspace, 'tsconfig.json');
const config = ts.readConfigFile(configPath, ts.sys.readFile);
const rootNames = ctx.files.filter(f => f.endsWith('.ts')).map(f => path.join(ctx.workspace, f));
const options = ts.parseJsonConfigFileContent(config.config, {...ts.sys, readDirectory: () => rootNames}, ctx.workspace).options;
const program = ts.createProgram(rootNames, options);
const checker = program.getTypeChecker();
const publicFile = program.getSourceFile(path.join(ctx.workspace, 'src/index.ts'));
const publicSymbol = checker.getExportsOfModule(checker.getSymbolAtLocation(publicFile)).find(s => s.name === 'getNamedType');
function canonical(s) { return s && (s.flags & ts.SymbolFlags.Alias) ? checker.getAliasedSymbol(s) : s; }
const target = canonical(publicSymbol);
const refs = [];
const excluded = [];
for (const filename of rootNames) {
  const sf = program.getSourceFile(filename);
  function visit(node) {
    if (ts.isIdentifier(node)) {
      const symbol = canonical(checker.getSymbolAtLocation(node));
      if (symbol === target) {
        const start = sf.getLineAndCharacterOfPosition(node.getStart(sf));
        const end = sf.getLineAndCharacterOfPosition(node.getEnd());
        const row = {target:'getNamedType',file:path.relative(ctx.workspace,filename),line:start.line+1,column:start.character,end_line:end.line+1,end_column:end.character};
        if (ts.isFunctionDeclaration(node.parent) && node.parent.name === node) excluded.push(row);
        else refs.push(row);
      }
    }
    ts.forEachChild(node, visit);
  }
  visit(sf);
}
refs.sort((a,b)=> a.file.localeCompare(b.file) || a.line-b.line || a.column-b.column);
const diagnostics = ts.getPreEmitDiagnostics(program);
console.log(JSON.stringify({references:refs,own_declarations_excluded:excluded.length,diagnostics:diagnostics.map(d=>({code:d.code,message:ts.flattenDiagnosticMessageText(d.messageText,' ')}))},null,2));
NODE"
